using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Tool implementations --------------------------------------------------------

/// <summary>Tools the research agent can invoke during its investigation.</summary>
static class ResearchTools
{
    private static readonly List<(string Title, string Content)> _notes = [];

    private static readonly HttpClient _http = new();

    [Description("Search the web for a query and return a list of result snippets. Use this to discover information about a topic.")]
    public static async Task<string> SearchWeb(
        [Description("The search query")] string query)
    {
        // Brave Search API (free tier). Falls back to a simulated result when no key is configured.
        var apiKey = Environment.GetEnvironmentVariable("BRAVE_API_KEY");
        if (string.IsNullOrWhiteSpace(apiKey))
        {
            return $"[simulated result] Top results for \"{query}\":\n"
                 + $"1. \"{query}\" - Wikipedia overview covering history, key concepts, and recent developments.\n"
                 + $"2. \"Understanding {query}\" - An in-depth tutorial with practical examples.\n"
                 + $"3. \"Latest research on {query}\" - A 2026 survey paper summarizing state-of-the-art findings.\n";
        }

        var request = new HttpRequestMessage(HttpMethod.Get,
            $"https://api.search.brave.com/res/v1/web/search?q={Uri.EscapeDataString(query)}&count=5");
        request.Headers.Add("X-Subscription-Token", apiKey);
        request.Headers.Accept.Add(new("application/json"));

        var response = await _http.SendAsync(request);
        response.EnsureSuccessStatusCode();

        using var doc = await JsonDocument.ParseAsync(await response.Content.ReadAsStreamAsync());
        var results = doc.RootElement.GetProperty("web").GetProperty("results");

        var lines = new List<string>();
        foreach (var r in results.EnumerateArray())
        {
            var title = r.GetProperty("title").GetString();
            var snippet = r.GetProperty("description").GetString();
            lines.Add($"- {title}: {snippet}");
        }

        return string.Join("\n", lines);
    }

    [Description("Save a research note. Use this to record important findings as you research.")]
    public static string SaveNote(
        [Description("Short title for the note")] string title,
        [Description("Body of the note")] string content)
    {
        _notes.Add((title, content));
        return $"Note saved ({_notes.Count} total).";
    }

    [Description("Retrieve all saved research notes so far.")]
    public static string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        return string.Join("\n\n", _notes.Select((n, i) =>
            $"--- Note {i + 1}: {n.Title} ---\n{n.Content}"));
    }
}

// --- Agent loop ------------------------------------------------------------------

var topic = args.Length > 0
    ? string.Join(' ', args)
    : PromptForTopic();

Console.WriteLine($"\n🔍 Researching: {topic}\n");

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";

IChatClient chatClient = new OpenAIClient(apiKey)
    .GetChatClient(model)
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

var tools = new[]
{
    AIFunctionFactory.Create(ResearchTools.SearchWeb),
    AIFunctionFactory.Create(ResearchTools.SaveNote),
    AIFunctionFactory.Create(ResearchTools.GetNotes),
};

var chatOptions = new ChatOptions { Tools = [.. tools] };

List<ChatMessage> messages =
[
    new(ChatRole.System, """
        You are a research agent. Your goal is to thoroughly research the given topic
        using the tools available to you.

        Follow this process:
        1. Search the web for the topic (try 2-3 different queries to get broad coverage).
        2. As you find important information, save notes using the SaveNote tool.
        3. After gathering enough information, retrieve your notes with GetNotes.
        4. Finally, write a well-structured summary of your findings.

        Be thorough but concise. Cite the sources you found.
        """),
    new(ChatRole.User, $"Please research the following topic and provide a summary: {topic}")
];

Console.WriteLine("Agent is working...\n");

var response = await chatClient.GetResponseAsync(messages, chatOptions);

Console.WriteLine("═══════════════════════════════════════════");
Console.WriteLine("  RESEARCH SUMMARY");
Console.WriteLine("═══════════════════════════════════════════\n");
Console.WriteLine(response.Text);
Console.WriteLine();

// --- helpers ---------------------------------------------------------------------

static string PromptForTopic()
{
    Console.Write("Enter a research topic: ");
    var topic = Console.ReadLine()?.Trim();
    if (string.IsNullOrWhiteSpace(topic))
    {
        Console.WriteLine("No topic provided. Using default topic.");
        topic = "the impact of artificial intelligence on scientific research";
    }
    return topic;
}

